using System;using System.IO;using System.Text;using System.Security.Cryptography;using System.Collections.Generic;
// Internal actual ground/pickup stage; full tower use/cleanup remains unreleased.
partial class Offline70BatchServiceFG {
 void TowerCleanupFG175(string reason){Offline70EconomyState before=Offline70Economy.Load(economyPath);if(!before.TowerTemporaryItemsFG175)return;bool duplicate;assets=Offline70Economy.Apply(economyPath,"tower-cleanup-175-"+before.Revision,"tower-cleanup",reason,delegate(Offline70EconomyState state){if(!state.TowerTemporaryItemsFG175)throw new InvalidDataException("Tower cleanup ownership changed");state.Inventory.RemoveAll(delegate(Offline70EconomyEntry e){return e.List==0&&e.ItemId>=6500&&e.ItemId<=6999;});state.TowerTemporaryItemsFG175=false;},out duplicate);Note("TOWER_TEMP_CLEANUP reason="+reason+" duplicate="+duplicate);}

 List<Offline70GroundFG> TowerDropsFG175(Offline70TowerActorFG171 actor,string receipt){int draw=0;int[] ids=Offline70TowerDropPlannerFG175.Plan(actor.Type,actor.Code,true,delegate(int maximum){using(SHA256 h=SHA256.Create())return (int)(BitConverter.ToUInt32(h.ComputeHash(Encoding.UTF8.GetBytes(receipt+"-tower-item-"+(draw++))),0)%(uint)maximum);});List<Offline70GroundFG> rows=new List<Offline70GroundFG>();HashSet<ushort> planned=new HashSet<ushort>();foreach(int id in ids){ushort slot=2000;while(ground.ContainsKey(slot)||picked.Contains(slot)||planned.Contains(slot))slot++;if(slot>Offline70FloorDropsFG119.LastSlot)throw new InvalidDataException("Tower ground capacity");Offline70GroundFG d=new Offline70GroundFG{Slot=slot,ItemId=(uint)id,Quantity=1,Receipt=receipt+"-tower-ground-"+rows.Count};planned.Add(slot);rows.Add(d);}return rows;}
 byte[] TowerDeathDropsFG175(ushort uid,List<Offline70GroundFG> rows){if(uid>=60000||rows.Count>255)throw new InvalidDataException("Tower death ground range");using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write(uid);w.Write((byte)rows.Count);foreach(Offline70GroundFG d in rows){w.Write(d.Slot);w.Write(d.ItemId);w.Write(d.Quantity);w.Write((ushort)0);w.Write((byte)0);w.Write((ushort)0);w.Write((uint)0);w.Write(new byte[6]);w.Write((ushort)65535);}w.Write(new byte[]{0,255,0});return m.ToArray();}}
 void TowerPickupFG175(byte[] body){try{if(!TowerActiveFG172||!towerLoadedFG172||playerDeadFG117||towerFinishingFG174)throw new InvalidDataException("Tower pickup state");byte[] request=Offline70RoleProtocol.BatchPickupRequestFG(body,keys);ushort slot=BitConverter.ToUInt16(request,0);if(picked.Contains(slot)){Ack(46,true);return;}Offline70GroundFG drop;if(!ground.TryGetValue(slot,out drop))throw new InvalidDataException("Unknown tower ground");Sync();Offline70EconomyState before=assets;bool duplicate;assets=Offline70Economy.Grant(economyPath,drop.Receipt,0,0,drop.ItemId,drop.Quantity,out duplicate);Sync();ushort destination=0;bool found=false;foreach(Offline70EconomyEntry e in assets.Inventory)if(e.ItemId==drop.ItemId){Offline70EconomyEntry previous=Offline70Economy.Find(before,e.List,e.Slot);if(previous==null||previous.ItemId!=e.ItemId||previous.Quantity!=e.Quantity){destination=e.Slot;found=true;break;}}if(!duplicate&&!found)throw new InvalidDataException("Tower pickup projection");ground.Remove(slot);picked.Add(slot);if(!duplicate)Send("tower-item-picked",Offline70RoleProtocol.BatchPacketFG(0,39,Offline70LootWireFG.Pickup(drop,destination),keys,true));Ack(46,true);Note("TOWER_PICKUP_COMMITTED slot="+slot+" item="+drop.ItemId+" duplicate="+duplicate);}catch(InvalidDataException e){Ack(46,false);Note("TOWER_PICKUP_REJECTED "+e.Message);}}
}
